CREATE TABLE tenant (id VARCHAR(64) PRIMARY KEY, name VARCHAR(120) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
INSERT INTO tenant(id,name) VALUES ('anysale','AnySale') ON CONFLICT (id) DO NOTHING;
ALTER TABLE lead ADD COLUMN tenant_id VARCHAR(64); UPDATE lead SET tenant_id='anysale' WHERE tenant_id IS NULL; ALTER TABLE lead ALTER COLUMN tenant_id SET NOT NULL; ALTER TABLE lead ADD CONSTRAINT fk_lead_tenant FOREIGN KEY (tenant_id) REFERENCES tenant(id); CREATE INDEX idx_lead_tenant_created ON lead(tenant_id,created_at DESC);
ALTER TABLE interaction ADD COLUMN tenant_id VARCHAR(64); UPDATE interaction i SET tenant_id=l.tenant_id FROM lead l WHERE i.lead_id=l.id; ALTER TABLE interaction ALTER COLUMN tenant_id SET NOT NULL; ALTER TABLE interaction ADD CONSTRAINT fk_interaction_tenant FOREIGN KEY (tenant_id) REFERENCES tenant(id); CREATE INDEX idx_interaction_tenant_lead ON interaction(tenant_id,lead_id,created_at);
ALTER TABLE lead_suggestion ADD COLUMN tenant_id VARCHAR(64); UPDATE lead_suggestion s SET tenant_id=l.tenant_id FROM lead l WHERE s.lead_id=l.id; ALTER TABLE lead_suggestion ALTER COLUMN tenant_id SET NOT NULL; ALTER TABLE lead_suggestion ADD CONSTRAINT fk_suggestion_tenant FOREIGN KEY (tenant_id) REFERENCES tenant(id);
ALTER TABLE lead_stage_history ADD COLUMN tenant_id VARCHAR(64); UPDATE lead_stage_history h SET tenant_id=l.tenant_id FROM lead l WHERE h.lead_id=l.id; ALTER TABLE lead_stage_history ALTER COLUMN tenant_id SET NOT NULL; ALTER TABLE lead_stage_history ADD CONSTRAINT fk_history_tenant FOREIGN KEY (tenant_id) REFERENCES tenant(id);
ALTER TABLE ai_settings ADD COLUMN tenant_id VARCHAR(64); UPDATE ai_settings SET tenant_id='anysale' WHERE tenant_id IS NULL; ALTER TABLE ai_settings ALTER COLUMN tenant_id SET NOT NULL; ALTER TABLE ai_settings ADD CONSTRAINT fk_ai_settings_tenant FOREIGN KEY (tenant_id) REFERENCES tenant(id); CREATE UNIQUE INDEX uk_ai_settings_tenant ON ai_settings(tenant_id);
ALTER TABLE ai_usage ADD COLUMN tenant_id VARCHAR(64); UPDATE ai_usage SET tenant_id='anysale' WHERE tenant_id IS NULL; ALTER TABLE ai_usage ALTER COLUMN tenant_id SET NOT NULL; ALTER TABLE ai_usage ADD CONSTRAINT fk_ai_usage_tenant FOREIGN KEY (tenant_id) REFERENCES tenant(id); CREATE INDEX idx_ai_usage_tenant_created ON ai_usage(tenant_id,created_at);
